-- v11 migration — Verse Hunt prompt bank (a Sword Drill twist).
-- Feeds the Verse Hunt game. Safe to run on live data (idempotent).
--
-- The leader reads `text` (a broad category) aloud; teams race to find ANY
-- verse that fits. `hint` is an example for the judge only. `books` is a couple
-- of recommended books to point students to if they need a starting place.
-- GENERATED by scripts/gen_verse_hunt.mjs.

create table if not exists verse_hunt_prompts (
  id uuid primary key default gen_random_uuid(),
  text text not null,
  difficulty text not null default 'medium',   -- easy | medium | hard
  hint text,                                   -- example verse, for the judge
  books text,                                  -- recommended books (student starting point)
  active boolean not null default true,
  created_at timestamptz not null default now()
);

-- Unique text lets the seed below be re-run safely (on conflict do nothing).
create unique index if not exists verse_hunt_prompts_text_key on verse_hunt_prompts (text);
create index if not exists verse_hunt_prompts_active_idx on verse_hunt_prompts (active, difficulty);

-- RLS disabled to match the other game tables (see gtf_questions).
alter table verse_hunt_prompts disable row level security;

-- Seed the 215-prompt bank. Re-running is safe: existing prompts are skipped.
on conflict (text) do nothing;
